const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');

// Security middleware configuration

// Helmet for securing HTTP headers
const securityHeaders = helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"]
    }
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true
  }
});

// CORS configuration - use environment variable or default to false for security
const corsOptions = cors({
  origin: process.env.ALLOWED_ORIGINS ? process.env.ALLOWED_ORIGINS.split(',') : false,
  credentials: true
});

// Rate limiting to prevent brute-force attacks
// Make rate limit configurable via environment variables
const rateLimiter = rateLimit({
  windowMs: parseInt(process.env.RATE_LIMIT_WINDOW_MS) || 15 * 60 * 1000, // 15 minutes default
  max: parseInt(process.env.RATE_LIMIT_MAX) || 100, // limit each IP to 100 requests per windowMs default
  message: 'Too many requests from this IP, please try again later.'
});

module.exports = {
  securityHeaders,
  corsOptions,
  rateLimiter
};

